public class ParkingLot{int twoWheelers=0,fourWheelers=0;final int twoCap,fourCap;static long revenue=0;ParkingLot(int a,int b){twoCap=a;fourCap=b;}boolean park(String type){if(type.equals("two")&&twoWheelers<twoCap){twoWheelers++;revenue+=20;return true;}if(type.equals("four")&&fourWheelers<fourCap){fourWheelers++;revenue+=40;return true;}System.out.println("Full");return false;}void leave(String t){if(t.equals("two")&&twoWheelers>0)twoWheelers--;if(t.equals("four")&&fourWheelers>0)fourWheelers--;}public static void main(String[]x){ParkingLot p=new ParkingLot(2,1);p.park("two");p.park("two");p.park("two");p.park("four");p.leave("two");System.out.println("Two="+p.twoWheelers+", Four="+p.fourWheelers+", Revenue="+revenue);}}
